import { MakeLogicType, actions, afterMount, kea, key, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import { membersMcpUsageRetrieve } from 'products/platform_features/frontend/generated/api'

interface MemberMcpUsageLogicProps {
    organizationId: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface memberMcpUsageLogicValues {
    mcpUsage: Record<string, string> | null
    mcpUsageLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface memberMcpUsageLogicActions {
    loadMcpUsage: () => {
        value: true
    }
    loadMcpUsageFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadMcpUsageSuccess: (
        mcpUsage: {
            [k: string]: string
        } | null,
        payload?: {
            value: true
        }
    ) => {
        mcpUsage: {
            [k: string]: string
        } | null
        payload?: {
            value: true
        }
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface memberMcpUsageLogicMeta {
    key: string
}

export type memberMcpUsageLogicType = MakeLogicType<
    memberMcpUsageLogicValues,
    memberMcpUsageLogicActions,
    MemberMcpUsageLogicProps,
    memberMcpUsageLogicMeta
>

export const memberMcpUsageLogic = kea<memberMcpUsageLogicType>([
    props({} as MemberMcpUsageLogicProps),
    key((props) => props.organizationId ?? 'unavailable'),
    path((key) => ['scenes', 'settings', 'organization', 'memberMcpUsageLogic', key]),
    actions({ loadMcpUsage: true }),
    loaders(({ props }) => ({
        mcpUsage: {
            __default: null as Record<string, string> | null,
            loadMcpUsage: async () => {
                if (!props.organizationId) {
                    return null
                }
                const response = await membersMcpUsageRetrieve(props.organizationId)
                return Object.fromEntries(
                    response.results.map((entry) => [entry.organization_membership_id, entry.last_mcp_used_at])
                )
            },
        },
    })),
    afterMount(({ actions }) => {
        actions.loadMcpUsage()
    }),
])
